from typing import List

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        prefix = []
        total = 0
        for s in skill:
            total += s
            prefix.append(total)

        start = 0

        for j in range(1, len(mana)):
            prev_mana = mana[j - 1]
            curr_mana = mana[j]

            delay = prev_mana * prefix[0]
            for i in range(1, len(skill)):
                delay = max(delay, prev_mana * prefix[i] - curr_mana * prefix[i - 1])

            start += delay

        return start + mana[-1] * prefix[-1]
